mapper.select:

SELECT request_fingerprint,
       knowledge_space_id::text AS knowledge_space_id,
       index_version_id::text AS index_version_id
FROM knowledge_data.index_version_request
WHERE tenant_id = #{tenantId}
  AND operation = #{operation}
  AND idempotency_key_hash = #{keyHash}

mapper.update:

UPDATE knowledge_data.index_build_job
SET status = 'RUNNING',
    attempt = attempt + 1,
    lease_id = #{leaseId},
    lease_until = #{leaseUntil},
    failure_code = NULL,
    completed_at = NULL
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND index_version_id = #{indexVersionId}

mapper.select:

SELECT 1
FROM knowledge_data.index_build_job
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND index_version_id = #{indexVersionId}
  AND status = 'RUNNING'
  AND lease_id = #{leaseId}
FOR UPDATE

mapper.update:

UPDATE knowledge_data.index_version
SET status = 'READY',
    version = version + 1,
    build_digest = #{buildDigest},
    chunk_count = #{chunkCount},
    ready_at = #{completedAt}
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND id = #{indexVersionId}
  AND status = 'BUILDING'


UPDATE knowledge_data.index_build_job
SET status = 'DONE',
    lease_id = NULL,
    lease_until = NULL,
    failure_code = NULL,
    completed_at = #{completedAt}
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND index_version_id = #{indexVersionId}
  AND status = 'RUNNING'
  AND lease_id = #{leaseId}


UPDATE knowledge_data.index_version
SET status = 'FAILED',
    version = version + 1,
    failure_code = #{failureCode}
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND id = #{indexVersionId}
  AND status = 'BUILDING'


UPDATE knowledge_data.index_build_job
SET status = 'FAILED',
    lease_id = NULL,
    lease_until = NULL,
    failure_code = #{failureCode},
    completed_at = #{failedAt}
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND index_version_id = #{indexVersionId}
  AND status = 'RUNNING'
  AND lease_id = #{leaseId}


UPDATE knowledge_data.index_version
SET status = 'SUPERSEDED',
    version = version + 1,
    superseded_at = #{supersededAt}
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND status = 'ACTIVE'


UPDATE knowledge_data.index_version
SET status = 'ACTIVE',
    version = version + 1,
    activated_at = #{activatedAt}
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND id = #{indexVersionId}
  AND status = 'READY'
  AND version = #{expectedVersion}
